#include <stdio.h>

int main(void) {
    int v, contas[3];
    scanf("%d%d%d%d", &v, &contas[0], &contas[1], &contas[2]);

    for (int i = 0; i < 3; i++) {
        for (int j = i + 1; j < 3; j++) {
            if (contas[j] < contas[i]) {
                int temp = contas[i];
                contas[i] = contas[j];
                contas[j] = temp;
            }
        }
    }

    int pagas = 0;
    for (int i = 0; i < 3; i++) {
        if (v >= contas[i]) {
            v -= contas[i];
            pagas++;
        } else {
            break;
        }
    }

    printf("%d\n", pagas);
    return 0;
}
